// ===== CALLS SYNC CONFIG =====
const LOOKBACK_DAYS = 35;
const BACKFILL_START = '';   // set '2026-01-01' for the first run, then back to ''
const DISPO = {
  'f240bbac-87c9-4f6e-bf70-924b57d47db7': ['Connected','connected'],
  'fbb23c68-d69d-484b-9ffb-928adacccc34': ['Meeting Booked','connected'],
  '351dfa83-f9c9-448c-bcd8-fa278a7e7eb5': ['Not interested','rejected'],
  '2d05f9d0-0e9e-4bd4-8ba3-878716827148': ['Wrong Person','rejected'],
  '56cf510f-a883-457e-8ab2-1b497a414238': ['Competitor/Partner','rejected'],
  'c1109a32-7bec-41f5-b5df-b33e42db2afb': ['No Budget','rejected'],
  '75debd7e-340b-4f1e-9247-87170ea2b9bd': ['No Productfit','rejected'],
  'c8df4524-aef4-422b-9d22-f1bf71ce9649': ['Solution in Place','rejected'],
  'eb62c822-ad58-4578-8709-48a9823e319b': ['Wrong Timing','rejected'],
  '9d9162e7-6cf3-4944-bf63-4dff82258764': ['Busy','no_contact'],
  '73a0d17f-1163-4015-bdd5-ec830791da20': ['No answer','no_contact'],
  'b2cf5968-551e-4856-9783-52b3da59a7d0': ['Left voicemail','no_contact'],
  'a4c4c377-d246-4b32-a13b-75a56a4cd0ff': ['Left live message','no_contact'],
  '17b47fee-58de-441e-a44c-c6300d46f273': ['Wrong number','no_contact'],
  '7e815e57-1158-4f20-9d3f-64f048bea013': ['Other','no_contact']
};

const DAY = 86400000; const now = Date.now();
let chunks = [];
if (BACKFILL_START) {
  let cur = Date.parse(BACKFILL_START);
  while (cur < now) { const d = new Date(cur); const nx = Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1);
    chunks.push({ fromMs: cur, toMs: Math.min(nx, now) }); cur = nx; }
} else { chunks = [{ fromMs: now - LOOKBACK_DAYS * DAY, toMs: now }]; }

return chunks.map(c => ({ json: { fromMs: c.fromMs, toMs: c.toMs, DISPO } }));

return $('Config').all().map(it => ({ json: { body: {
  filterGroups: [{ filters: [
    { propertyName: 'hs_timestamp', operator: 'GTE', value: String(it.json.fromMs) },
    { propertyName: 'hs_timestamp', operator: 'LT', value: String(it.json.toMs) }]}],
  properties: ['hs_call_disposition','hs_timestamp','hubspot_owner_id','hs_call_duration'],
  sorts: [{ propertyName: 'hs_object_id', direction: 'ASCENDING' }], limit: 200 } } }));

const calls = {}; for (const it of $input.all()) for (const r of (it.json.results || [])) calls[r.id] = r;
const ids = Object.keys(calls);
const out = [];
for (const to of ['companies','contacts'])
  for (let i = 0; i < ids.length; i += 100)
    out.push({ json: { to, url: 'https://api.hubapi.com/crm/v4/associations/calls/' + to + '/batch/read',
      body: { inputs: ids.slice(i, i + 100).map(id => ({ id })) } } });
if (!out.length) return [{ json: { skip: true } }];
return out;

const pi = it => it.pairedItem ? (typeof it.pairedItem === 'number' ? it.pairedItem : it.pairedItem.item) : 0;

const reqs = $('Build Assoc').all();
const cids = new Set();
for (const it of $input.all()) {
  const meta = reqs[pi(it)] ? reqs[pi(it)].json : {};
  if (meta.to !== 'contacts') continue;
  for (const r of (it.json.results || [])) for (const t of (r.to || [])) cids.add(String(t.toObjectId));
}
const ids = [...cids];
if (!ids.length) return [{ json: { skip: true, has: false } }];
const out = [];
for (let i = 0; i < ids.length; i += 100)
  out.push({ json: { has: true, body: { inputs: ids.slice(i, i + 100).map(id => ({ id })), properties: ['associatedcompanyid','firstname','lastname','hs_persona'] } } });
return out;

const pi = it => it.pairedItem ? (typeof it.pairedItem === 'number' ? it.pairedItem : it.pairedItem.item) : 0;

const reqs = $('Build Assoc').all();
const assoc = $('Read Assoc').all();
const callToCompany = {}, callToContacts = {};
for (const it of assoc) {
  const meta = reqs[pi(it)] ? reqs[pi(it)].json : {};
  for (const r of (it.json.results || [])) {
    const f = String(r.from && r.from.id);
    if (meta.to === 'companies') callToCompany[f] = String((r.to || [])[0] ? r.to[0].toObjectId : '');
    if (meta.to === 'contacts') callToContacts[f] = (r.to || []).map(t => String(t.toObjectId));
  }
}
const contacts = {};
for (const it of $input.all()) { if (it.json.skip) continue;
  for (const r of (it.json.results || [])) { const p = r.properties || {};
    contacts[String(r.id)] = { companyId: p.associatedcompanyid || null, persona: p.hs_persona || null,
      name: ((p.firstname || '') + ' ' + (p.lastname || '')).trim() }; } }
const compIds = new Set(Object.values(callToCompany).filter(Boolean));
for (const v of Object.values(contacts)) if (v && v.companyId) compIds.add(String(v.companyId));
const ids = [...compIds];
const out = [];
for (let i = 0; i < ids.length; i += 100)
  out.push({ json: { body: { inputs: ids.slice(i, i + 100).map(id => ({ id })), properties: ['name','publisher_type'] } } });
if (!out.length) out.push({ json: { skip: true } });
return [{ json: { callToCompany, callToContacts, contacts } }, ...out];

const esc = v => v === null || v === undefined || v === '' ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const num = v => v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : String(Number(v));
const bool = v => v ? 'true' : 'false';

const owners = {};
for (const o of ($('Get Owners').first().json.results || []))
  owners[String(o.id)] = ((o.firstName || '') + ' ' + (o.lastName || '')).trim() || o.email || String(o.id);

const pi = it => it.pairedItem ? (typeof it.pairedItem === 'number' ? it.pairedItem : it.pairedItem.item) : 0;

const state = $('Build Company Reads').all()[0].json;
const names = {};
for (const it of $input.all()) for (const r of ((it.json || {}).results || [])) names[String(r.id)] = { name: (r.properties || {}).name || '', icp: (r.properties || {}).publisher_type || null };
const cfg = $('Config').all()[0].json;
const rows = [];
const seen = new Set();
for (const it of $('Search Calls').all()) for (const c of (it.json.results || [])) {
  if (seen.has(c.id)) continue; seen.add(c.id);
  const p = c.properties || {};
  const [label, bucket] = cfg.DISPO[p.hs_call_disposition] || ['Unknown','no_contact'];
  let comp = state.callToCompany[String(c.id)] || null;
  let contactId = null, contactName = '', persona = null;
  for (const ct of (state.callToContacts[String(c.id)] || [])) {
    const co = state.contacts[ct];
    if (!contactId) { contactId = ct; contactName = co ? co.name : ''; persona = co ? co.persona : null; }
    if (!comp && co && co.companyId) comp = String(co.companyId);
  }
  const compInfo = comp ? names[comp] || {} : {};
  const PL = { persona_17:'Adtech', persona_9:'Agency', persona_18:'Audience', persona_15:'Commercial & Sales',
    persona_1:'Data & Analytics', persona_8:'Engineering & IT', persona_7:'Executive', persona_3:'E-Commerce',
    persona_10:'Legal', persona_6:'Marketing - General', persona_4:'Marketing - Performance', persona_16:'Product',
    persona_12:'Reader Revenue & Subscription', persona_11:'No fitting persona' };
  rows.push('(' + [num(c.id), esc(new Date(Number(p.hs_timestamp) || Date.parse(p.hs_timestamp)).toISOString()),
    esc(owners[String(p.hubspot_owner_id)] || 'Unknown'), esc(p.hs_call_disposition), esc(label), esc(bucket),
    num(comp), esc(compInfo.name || ''), num(contactId), esc(contactName), esc(compInfo.icp), esc(persona ? PL[persona] || persona : null), num(p.hs_call_duration ? Math.round(p.hs_call_duration / 1000) : null)].join(',') + ')');
}
if (!rows.length) return [{ json: { sql: 'SELECT 1;' } }];
return [{ json: { sql: 'INSERT INTO calls (call_id,ts,owner_name,disposition_id,disposition_label,bucket,company_id,company_name,contact_id,contact_name,icp_type,persona,duration_seconds) VALUES\n' +
  rows.join(',\n') + '\nON CONFLICT (call_id) DO UPDATE SET ts=EXCLUDED.ts, owner_name=EXCLUDED.owner_name, disposition_id=EXCLUDED.disposition_id, disposition_label=EXCLUDED.disposition_label, bucket=EXCLUDED.bucket, company_id=EXCLUDED.company_id, company_name=EXCLUDED.company_name, contact_id=EXCLUDED.contact_id, contact_name=EXCLUDED.contact_name, icp_type=EXCLUDED.icp_type, persona=EXCLUDED.persona, duration_seconds=EXCLUDED.duration_seconds;' } }];
